export const connector = defineConnector({
  name: "modjo",
  label: "Modjo",
  namespace: "modjo",
  version: "1.0.0",
  apiVersion: "v2",
  baseUrl: "https://api.modjo.ai/v2",
  auth: {"kind": "bearer", "token": "api_key"},
  credential: [{"name": "api_key", "label": "Workspace API key", "secret": true, "holder": "account"}],
  modes: ["byo_user", "byo_org"],
  timeoutMs: 60000,
  queryArrays: "comma",
  rateLimit: { requests: 100, intervalMs: 60000 },
  errors: [
    { status: 400, code: "invalid_request", message: "Modjo rejected the request as invalid: check the arguments.", retryable: false },
    { status: 401, code: "access_rejected", message: "Modjo rejected the API key: it is missing, invalid or revoked.", retryable: false },
    { status: 403, code: "not_enabled", message: "This Modjo feature is not enabled for the workspace.", retryable: false },
    { status: 404, code: "not_found", message: "Modjo object not found.", retryable: false },
    { status: 409, code: "conflict", message: "Modjo refused the operation: the object is not ready yet, or already exists.", retryable: false },
    { status: 410, code: "gone", message: "Deleted for good by the workspace's retention policy.", retryable: false },
    { status: 429, code: "rate_limited", message: "Modjo rate limit reached (100 requests per minute for the whole workspace): retry after the window resets.", retryable: true },
    { status: [500, 502, 503, 504], code: "upstream_unavailable", message: "Modjo is temporarily unavailable: retry later.", retryable: true },
  ],
  probe: { function: "modjo.list_tags", nonEmpty: [] },
  exposure: {"mode": "per_connector", "tool": "modjo"},
  functions: [
    listCalls,
    getCall,
    getCallTranscript,
    listCallSummaries,
    listCallNotes,
    listCallNextSteps,
    getCallRecording,
    listCallCrmFillingAnswers,
    listCallTags,
    addCallTag,
    removeCallTag,
    uploadCall,
    listCallReviews,
    listAccounts,
    getAccount,
    listContacts,
    getContact,
    listDeals,
    getDealSummary,
    listTags,
    listTopics,
    listUsers,
    getUser,
    listTeams,
    getTeam,
    listTeamMembers,
    listCrmFillingTemplates,
    getCrmFillingTemplate,
    listCrmFillingTemplateFields,
  ],
})
